<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,allPages,fmtDate} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import EmptyState from '../components/EmptyState.vue';import {Plus,FolderOpen,ArrowUpRight,Search,Images} from 'lucide-vue-next'
const rows=ref<any[]>([]),show=ref(false),search=ref(''),form=ref({name:'',description:'',source:'',license:''});const {error,success,busy,act}=usePage()
const load=()=>act(async()=>{rows.value=await allPages('datasets/?search='+encodeURIComponent(search.value))});onMounted(load)
const save=()=>act(async()=>{await api.post('datasets/',form.value);show.value=false;form.value={name:'',description:'',source:'',license:''};rows.value=await allPages('datasets/')},'Colección registrada. Ahora puedes importar tu dataset existente.')
</script>
<template><div class="mb-7 flex flex-wrap justify-between gap-4"><div><h1 class="heading">Tus datos, organizados.</h1><p class="subheading">Importa las imágenes y etiquetas que ya tienes. Conserva su origen y cada revisión.</p></div><button class="btn self-start" @click="show=!show"><Plus :size="17"/>Registrar colección</button></div><Notice :error="error" :success="success"/>
<form v-if="show" @submit.prevent="save" class="card mb-6 grid gap-4 md:grid-cols-2"><div><label class="label">Nombre de la colección</label><input v-model="form.name" class="input" required maxlength="160" placeholder="Paltas Hass · Dataset de tesis"/></div><div><label class="label">Procedencia</label><input v-model="form.source" class="input" placeholder="Fuente propia, institución o URL"/></div><div><label class="label">Descripción</label><textarea v-model="form.description" class="input"/></div><div><label class="label">Licencia o autorización de uso</label><input v-model="form.license" class="input"/></div><div class="flex gap-3"><button class="btn" :disabled="busy">Guardar colección</button><button type="button" class="btn-secondary" @click="show=false">Cancelar</button></div></form>
<form class="mb-6 flex max-w-md gap-2" @submit.prevent="load"><input v-model="search" class="input" placeholder="Buscar una colección…" aria-label="Buscar colección"/><button class="btn-secondary" aria-label="Buscar"><Search :size="17"/></button></form>
<div v-if="rows.length" class="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><RouterLink v-for="item in rows" :key="item.id" :to="'/datasets/'+item.id" class="card group transition hover:-translate-y-1 hover:border-emerald-300 hover:shadow-md"><div class="mb-7 flex justify-between"><span class="rounded-xl bg-[#edf3df] p-3 text-forest"><FolderOpen :size="26"/></span><ArrowUpRight class="text-slate-300 group-hover:text-forest" :size="19"/></div><span v-if="item.archived" class="badge mb-2">Archivada</span><h2 class="text-lg font-semibold">{{item.name}}</h2><p class="mt-2 line-clamp-2 min-h-10 text-xs leading-5 text-slate-400">{{item.description||'Colección de imágenes para investigación.'}}</p><div class="mt-6 flex justify-between border-t border-slate-100 pt-4 text-xs text-slate-500"><span class="flex items-center gap-1.5"><Images :size="14"/>{{item.image_count}} imágenes</span><span>{{new Date(item.created_at).toLocaleDateString('es-PE')}}</span></div></RouterLink></div><EmptyState v-else title="Da un lugar a tu dataset" text="Registra una colección e importa tus imágenes o un ZIP con etiquetas YOLO. No necesitas volver a recolectar tus datos."/></template>
